    noaa_cols = noaa_wildfires.columns.tolist()
    raws_cols = raws_stations.columns.tolist()

    result = {
        'noaa_columns': ','.join(noaa_cols),
        'raws_columns': ','.join(raws_cols),
        'noaa_rows': len(noaa_wildfires),
        'raws_rows': len(raws_stations)
    }

    return pd.DataFrame([result])

def process(noaa_wildfires, raws_stations):
    noaa_cols = set(noaa_wildfires.columns)
    raws_cols = set(raws_stations.columns)

    # Check for any common columns
    common = noaa_cols & raws_cols
    noaa_only = noaa_cols - raws_cols
    raws_only = raws_cols - noaa_cols

    result_data = []
    result_data.append({
        'category': 'common_columns',
        'columns': ', '.join(sorted(common)) if common else 'None'
    })
    result_data.append({
        'category': 'noaa_only_columns',
        'columns': ', '.join(sorted(list(noaa_only)[:10]))
    })
    result_data.append({
        'category': 'raws_only_columns',
        'columns': ', '.join(sorted(list(raws_only)[:10]))
    })

    return pd.DataFrame(result_data)

